/** Stateless, public-only Agent Reach-compatible MCP adapter. No account credentials. */
export const MCP_VERSION = '2025-06-18';
export const CHANNEL_DOMAINS = Object.freeze({
  web: null,
  youtube: 'youtube.com',
  github: 'github.com',
  reddit: 'reddit.com',
  twitter: 'x.com',
  facebook: 'facebook.com',
  instagram: 'instagram.com',
  bilibili: 'bilibili.com',
  xiaohongshu: 'xiaohongshu.com',
  linkedin: 'linkedin.com',
  boss: 'zhipin.com',
  v2ex: 'v2ex.com',
  xueqiu: 'xueqiu.com',
  xiaoyuzhou: 'xiaoyuzhoufm.com',
});

const text = (description) => ({ type: 'string', description });
const schema = (properties, required = []) => ({ type: 'object', properties, required, additionalProperties: false });
const tool = (name, description, inputSchema) => ({
  name, description, inputSchema,
  annotations: { title: name.replaceAll('_', ' '), readOnlyHint: true, destructiveHint: false, idempotentHint: true, openWorldHint: true },
});
export const TOOLS = Object.freeze([
  tool('reach_search', 'Search the public web with Agent Reach web backend (Exa hosted search). Returns real source links and excerpts.', schema({query: text('Search query, maximum 300 characters'), limit: {type: 'integer', minimum: 1, maximum: 8, default: 5}}, ['query'])),
  tool('reach_read', 'Read a public webpage using Jina Reader. Source text can be incomplete or anti-bot blocked.', schema({url: text('Public HTTPS URL (not localhost, private IP, or credentialed URL)')}, ['url'])),
  tool('reach_channel_search', 'Search public web-indexed material on one of fourteen Agent Reach channels; this is web-indexed discovery, not authenticated/native site search.', schema({channel: {type: 'string', enum: Object.keys(CHANNEL_DOMAINS)}, query: text('Search query'), limit: {type: 'integer', minimum: 1, maximum: 8, default: 5}}, ['channel', 'query'])),
  tool('reach_github', 'Read a public GitHub repository metadata, README or matching issue (no account access).', schema({repository: text('owner/repo'), resource: {type: 'string', enum: ['repository', 'readme', 'issues'], default: 'repository'}}, ['repository'])),
  tool('reach_youtube', 'Read public YouTube video metadata using oEmbed; this does not supply transcripts.', schema({video: text('YouTube 11-character video ID or public video URL')}, ['video'])),
  tool('reach_channels', 'Show supported platform routes and the difference between native and indexed access.', schema({}, [])),
]);

export class ReachError extends Error {
  constructor(code, message) { super(message); this.code = code; }
}
function boundedString(raw, label, max = 300) {
  if (typeof raw !== 'string' || !raw.trim() || raw.length > max || /[\x00-\x1f\x7f]/.test(raw)) {
    throw new ReachError('BAD_INPUT', `${label} must contain 1-${max} printable characters`);
  }
  return raw.trim();
}
function boundedLimit(raw) {
  if (raw == null) return 5;
  if (!Number.isInteger(raw) || raw < 1 || raw > 8) throw new ReachError('BAD_INPUT', 'limit must be an integer 1-8');
  return raw;
}
export function publicUrl(raw) {
  const value = boundedString(raw, 'url', 1800);
  let url;
  try { url = new URL(value); } catch { throw new ReachError('BAD_INPUT', 'invalid URL'); }
  if (url.protocol !== 'https:' || url.username || url.password || url.port) throw new ReachError('BAD_INPUT', 'only ordinary public HTTPS URLs without credentials or ports are allowed');
  const host = url.hostname.toLowerCase();
  if (!host.includes('.') || host === 'localhost' || host.endsWith('.localhost') || host.endsWith('.local') || host.endsWith('.internal') || host.endsWith('.test') || host.endsWith('.invalid') || host.endsWith('.onion') || /^\d+\.\d+\.\d+\.\d+$/.test(host) || host.startsWith('[')) throw new ReachError('BAD_INPUT', 'private or non-public URL not permitted');
  return url.toString();
}
function fromUrl(video) {
  const raw = boundedString(video, 'video', 500);
  if (/^[A-Za-z0-9_-]{11}$/.test(raw)) return raw;
  const url = new URL(publicUrl(raw));
  const host = url.hostname.toLowerCase().replace(/^www\./, '');
  let id = null;
  if (host === 'youtu.be') id = url.pathname.slice(1);
  else if (host === 'youtube.com' || host === 'm.youtube.com') id = url.searchParams.get('v');
  if (!id || !/^[A-Za-z0-9_-]{11}$/.test(id)) throw new ReachError('BAD_INPUT', 'not a YouTube watch URL or video ID');
  return id;
}
function asText(payload) {
  const str = typeof payload === 'string' ? payload : JSON.stringify(payload);
  return [{type:'text',text: str.length <= 25000 ? str : str.slice(0, 25000) + '\n[truncated]'}];
}
async function request(url, opts = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), 16000);
  try {
    const r = await fetch(url, { ...opts, signal: controller.signal });
    if (r.status === 429) throw new ReachError('RATE_LIMITED', `Provider returned HTTP 429`);
    if (!r.ok) throw new ReachError('UPSTREAM_ERROR', `Provider returned HTTP ${r.status}`);
    const body = await r.text();
    if (body.length > 700000) throw new ReachError('UPSTREAM_ERROR', 'Response too large');
    return body;
  } catch(e) {
    if (e instanceof ReachError) throw e;
    throw new ReachError('UPSTREAM_ERROR', e.name === 'AbortError' ? 'Provider timeout' : 'Provider unavailable');
  } finally { clearTimeout(timer); }
}
async function exaSearch(query, limit) {
  const res = await request('https://mcp.exa.ai/mcp', {
    method: 'POST', headers: {'content-type': 'application/json', 'accept': 'application/json, text/event-stream'},
    body: JSON.stringify({jsonrpc:'2.0',id:1,method:'tools/call',params:{name:'web_search_exa',arguments:{query,numResults:limit,objective:query}}}),
  });
  const lines = res.split('\n').filter((line)=>line.startsWith('data:')).map((line)=>line.slice(5).trim());
  let parsed;
  try { parsed = JSON.parse(lines.length ? lines[lines.length-1] : res); }
  catch { throw new ReachError('UPSTREAM_ERROR', 'Exa response was not valid JSON'); }
  if (parsed.error || parsed.result?.isError) throw new ReachError('UPSTREAM_ERROR', 'Exa returned an error');
  const items = parsed.result?.content?.filter((x) => x.type === 'text').map((x) => x.text) || [];
  if (items.length === 0) throw new ReachError('UPSTREAM_ERROR', 'Exa returned no readable result');
  return {backend:'exa', mode:'public-indexed', query, text: items.join('\n').slice(0, 24000)};
}
async function jinaRead(url) {
  const target=publicUrl(url);
  const body=await request(`https://r.jina.ai/${target}`,{headers:{accept:'text/plain','user-agent':'GMRI-Agent-Reach/1.0'}});
  if (/Just a moment\.\.\.|Performing security verification|requiring CAPTCHA/i.test(body.slice(0,1800))) throw new ReachError('BLOCKED','Reader returned a verification or CAPTCHA page');
  return {backend:'jina',source:target,completeness_verified:false,text:body.slice(0, 24000)};
}
async function github(repository, resource = 'repository') {
  const repo=boundedString(repository, 'repository', 150);
  if(!/^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(repo)) throw new ReachError('BAD_INPUT', 'repository must be owner/repo');
  if(!['repository','readme','issues'].includes(resource)) throw new ReachError('BAD_INPUT', 'unknown resource');
  const suffix=resource === 'repository' ? '' : resource === 'readme' ? '/readme' : '/issues?per_page=5&state=all';
  const url=`https://api.github.com/repos/${repo}${suffix}`;
